--- from: Assets/BundleResources/Arts/GachaponRes/119000/DiscGoodsNode.prefab > name: DiscGoodsNode
---@class GachaponStepDiscGoodsNode
---@field Env                           	GachaponStepDiscGoodsNode               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgGoodIcon                   	UnityEngine.RectTransform               	@ 0    
---@field ImgFree                       	UnityEngine.RectTransform               	@ 1    
---@field ImgLock                       	UnityEngine.RectTransform               	@ 2    
---@field ImgFinish                     	UnityEngine.RectTransform               	@ 3    
---@field ImgNext                       	UnityEngine.RectTransform               	@ 4    
local GachaponStepDiscGoodsNode = Class("GachaponStepDiscGoodsNode")
local CommonCurrencyNode = "Game.Behaviours.CommonCurrencyNode"

function GachaponStepDiscGoodsNode:__init()
    self.index = nil
    self.currencyEnv = nil
end

function GachaponStepDiscGoodsNode:__delete()
    self.index = nil
    self.currencyEnv = nil
    self.controller = nil
end

function GachaponStepDiscGoodsNode:Awake()
    self:InitNodeEnv()
end

function GachaponStepDiscGoodsNode:InitNodeEnv()
    local env = CfUtils.GetLuaScr(self.ImgGoodIcon,CommonCurrencyNode)
    if isNotNull(env) then
        self.currencyEnv = env
    end
end

function GachaponStepDiscGoodsNode:SetCurIndex(index, isUnLock)
    self.index = index
    self.isUnLock = isUnLock
end

function GachaponStepDiscGoodsNode:RefreshShow(data, curStep, index, isMaxTurn)
    self.data = data
    local isUnLock = self.isUnLock
    CfUtils.SetActive(self.ImgLock.gameObject,not isUnLock)
    self:SetCurrencyShow()
    if isUnLock then
        local isFinish = curStep > index
        CfUtils.SetActive(self.ImgFinish.gameObject, isFinish)
        local isNext = self.index == 2
        local isMaxTurn = isMaxTurn
        if isMaxTurn and curStep > index and isNext then
            isNext = false
        end
        CfUtils.SetActive(self.ImgNext.gameObject, isNext)
        
        local state = isFinish and 2 or 1
        local color = isFinish and "#939393" or "#FFFFFF"
        self.currencyEnv:SetColorAndState(color, state)
        CfUtils.SetUISwitchImage(self.ImgFree.gameObject, state)
    else
        CfUtils.SetActive(self.ImgFinish.gameObject,false)
        CfUtils.SetActive(self.ImgNext.gameObject,false)
        
        local color = "#939393"
        self.currencyEnv:SetColorAndState(color, 2)
        CfUtils.SetUISwitchImage(self.ImgFree.gameObject, 2)
    end
end

function GachaponStepDiscGoodsNode:SetCurrencyShow()
    local isFree = self.data.goodsId == 0 or self.data.num == 0
    CfUtils.SetActive(self.ImgGoodIcon.gameObject,not isFree)
    CfUtils.SetActive(self.ImgFree.gameObject, isFree)
    if not isFree then
        self.currencyEnv:SetCurrencyShow(self.data.goodsId,nil, "x"..self.data.num)
    end
end

function GachaponStepDiscGoodsNode:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return GachaponStepDiscGoodsNode